// stlport
//
// Default-flag (speed) out-of-line copy of the CDownload header constructor; the WWDownload unit that owns it is not size-optimised.
//
// The compiler-generated vector constructor iterator (??_H) takes the
// optimization state of the first function that needs it. Retail links one
// copy, the /O1 body at 0x00001423; this unemitted anchor makes this unit's
// copy that same body, so it no longer loses to retail's at link time.
// It can also change how later array constructions here compile; checked to
// change nothing else in this unit, but if a function added later that builds
// an array will not match, try it without this block.
struct BfmeVciAnchorElem { BfmeVciAnchorElem(); };
#pragma optimize("gsy", on)
static void bfmeVciAnchor() { BfmeVciAnchorElem anchor[2]; (void)anchor; }
#include "PreRTS.h"	// This must go first in EVERY cpp file int the GameEngine
#include "GameClient/GameText.h"
#include "GameNetwork/DownloadManager.h"

#pragma inline_depth(0)
// ?_bfmeCDownloadCtorAnchor@@ absent-from-retail
void _bfmeCDownloadCtorAnchor(CDownload *download, IDownload *listener)
{
	download->CDownload::CDownload(listener);
}
#pragma inline_depth()

